export function genericPowerCentres(n) {
  const aut = n.ideology === 'aut' || n.ideology === 'com' || n.ideology === 'the';
  const junta = /junta/i.test(n.gov);
  const rows = aut
    ? [['military', 'Armed forces', junta ? 34 : 22], ['security', 'Security services', 18], ['business', 'Business elites', 16], ['regions', 'Regional power brokers', 12], ['clergy', 'Religious institutions', n.ideology === 'the' ? 22 : 8], ['media', 'State media', 8]]
    : [['business', 'Business elites', 24], ['labor', 'Unions', 16], ['military', 'Armed forces', 12], ['media', 'Media', 16], ['regions', 'Regional movements', 12], ['security', 'Security services', 8], ['clergy', 'Religious institutions', 8]];
  const base = Math.max(15, Math.min(85, n.stability + 5));
  // Armies that already hold power, or have stayed in barracks so far, start out loyal.
  return rows.map(([type, name, influence], i) => ({ type, name, influence, loyalty: Math.round(type === 'military' ? Math.max(48, base + 12) : base + ((i * 37) % 21) - 10) }));
}

